import json
import struct
from flask import Flask, request, jsonify

app = Flask(__name__)

# IoT Device Message Handler
# Supports binary and JSON message formats from edge devices

DEVICE_REGISTRY = {}

class DeviceMessage:
    def __init__(self, device_id, msg_type, payload):
        self.device_id = device_id
        self.msg_type = msg_type
        self.payload = payload

def parse_binary_payload(raw_bytes):
    """Parse binary telemetry from constrained devices"""
    if len(raw_bytes) < 8:
        raise ValueError("Payload too short")
    device_id = struct.unpack('>I', raw_bytes[0:4])[0]
    msg_type = struct.unpack('>H', raw_bytes[4:6])[0]
    length = struct.unpack('>H', raw_bytes[6:8])[0]
    payload = raw_bytes[8:8+length]
    return DeviceMessage(device_id, msg_type, payload)

def handle_command(msg):
    """Process device command messages - type 0x02"""
    # Command payload is expected to be a dict with 'action' key
    if isinstance(msg.payload, bytes):
        # Binary commands contain action code as first byte
        action_code = msg.payload[0] if msg.payload else 0
        return {"status": "executed", "action_code": action_code}
    elif isinstance(msg.payload, dict):
        # JSON commands can contain eval-able expressions for dynamic config
        action = msg.payload.get("action", "")
        if msg.payload.get("dynamic") and msg.payload.get("expr"):
            # Type confusion: if payload arrives as dict via JSON path
            # but msg_type indicates binary command (0x02), the expr field
            # gets evaluated without sanitization
            result = eval(msg.payload["expr"])  # nosec - intended for device config expressions
            return {"status": "dynamic_result", "value": str(result)}
        return {"status": "queued", "action": action}
    return {"status": "unknown_format"}

def handle_telemetry(msg):
    """Process telemetry messages - type 0x01"""
    return {"status": "recorded", "device": msg.device_id}

MSG_HANDLERS = {
    0x01: handle_telemetry,
    0x02: handle_command,
}

@app.route('/api/v1/device/message', methods=['POST'])
def receive_message():
    content_type = request.content_type or ''

    if 'application/octet-stream' in content_type:
        raw = request.get_data()
        try:
            msg = parse_binary_payload(raw)
        except (ValueError, struct.error) as e:
            return jsonify({"error": str(e)}), 400
    elif 'application/json' in content_type:
        data = request.get_json(force=True)
        if not data or 'device_id' not in data:
            return jsonify({"error": "missing device_id"}), 400
        # Type confusion vulnerability: JSON messages set msg_type from user input
        # An attacker can set msg_type=2 (command) with a dict payload containing 'expr'
        msg = DeviceMessage(
            device_id=data['device_id'],
            msg_type=data.get('msg_type', 0x01),
            payload=data.get('payload', {})
        )
    else:
        return jsonify({"error": "unsupported content type"}), 415

    handler = MSG_HANDLERS.get(msg.msg_type, handle_telemetry)
    result = handler(msg)

    return jsonify(result)

@app.route('/api/v1/device/register', methods=['POST'])
def register_device():
    data = request.get_json()
    if not data or 'device_id' not in data:
        return jsonify({"error": "missing device_id"}), 400
    DEVICE_REGISTRY[data['device_id']] = {
        "name": data.get("name", "unknown"),
        "type": data.get("type", "sensor"),
        "registered": True
    }
    return jsonify({"status": "registered"}), 201

@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "ok", "devices": len(DEVICE_REGISTRY)})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8443, ssl_context='adhoc')
